{% set stamp = state_attr('sensor.iptime_neteuweokeu_jindan', 'last_success') %}
{% if stamp %}
{% set age = (as_timestamp(now()) - as_timestamp(stamp)) | int %}
{% if age > 86400 %}⚠️ **지난 진단 결과** · {% else %}✅ **마지막 진단** · {% endif %}
{{ as_timestamp(stamp) | timestamp_custom('%m/%d %H:%M', true) }} ({{ relative_time(as_datetime(stamp)) }} 전)
{% else %}
ℹ️ **아직 상세 진단을 수집하지 않았습니다.** 아래 버튼을 누르면 새 결과가 표시됩니다.
{% endif %}

{% set matches = states.sensor | selectattr('name', 'eq', 'ipTIME 포트 진단') | list %}
{% if not matches %}
ℹ️ 새 상세 진단 코드는 HA에 설치됐지만 아직 로드되지 않았습니다. HA 재시작 후 포트·기기·DHCP 상세가 표시됩니다.
{% endif %}

{% set stamp = state_attr('sensor.iptime_neteuweokeu_jindan', 'last_success') %}
{% if stamp %}
{% set age = (as_timestamp(now()) - as_timestamp(stamp)) | int %}
{% if age > 86400 %}⚠️ **지난 진단 결과** · {% else %}✅ **마지막 진단** · {% endif %}
{{ as_timestamp(stamp) | timestamp_custom('%m/%d %H:%M', true) }} ({{ relative_time(as_datetime(stamp)) }} 전)
{% else %}
ℹ️ **아직 상세 진단을 수집하지 않았습니다.** 아래 버튼을 누르면 새 결과가 표시됩니다.
{% endif %}

{% set matches = states.sensor | selectattr('name', 'eq', 'ipTIME 포트 진단') | list %}
{% set rows = matches[0].attributes.get('entries', []) if matches else [] %}
{% if not matches %}
통합 업데이트와 HA 재시작 후 포트 진단을 볼 수 있습니다.
{% elif not rows %}
수집된 포트 정보가 없습니다. **상세 진단 수집**을 눌러 주세요.
{% else %}
| 포트 | 연결 속도 | 내려받음 사용량 | 올림 사용량 | 오류 증가 |
|:--|:--|--:|--:|--:|
{% for p in rows %}| {{ (p.type or '포트') | upper }} {{ p.port }} | {{ p.link_label or '확인 불가' }} | {{ ((p.rx_mbps | float) | round(2) | string) ~ ' Mbps' if p.rx_mbps is defined and p.rx_mbps is not none else '—' }} | {{ ((p.tx_mbps | float) | round(2) | string) ~ ' Mbps' if p.tx_mbps is defined and p.tx_mbps is not none else '—' }} | {{ ((p.rx_crc_delta | int) + (p.rx_drop_delta | int) + (p.tx_collision_delta | int)) if p.rx_crc_delta is defined and p.rx_drop_delta is defined and p.tx_collision_delta is defined else '—' }} |
{% endfor %}

연결 속도는 포트의 연결 규격, 사용량은 마지막 진단 약 10초간 실제 흐른 양입니다. 오류 증가는 CRC·드롭·충돌의 합계입니다. `—`는 측정값이 없다는 뜻입니다.
{% endif %}

{% set matches = states.sensor | selectattr('name', 'eq', 'ipTIME 접속 기기 진단') | list %}
{% set rows = matches[0].attributes.get('entries', []) if matches else [] %}
{% if not matches %}
통합 업데이트와 HA 재시작 후 접속 기기 상세를 볼 수 있습니다.
{% elif not rows %}
수집된 접속 기기가 없습니다. **상세 진단 수집**을 눌러 주세요.
{% else %}
| 기기 | IP | 연결 | 신호 |
|:--|:--|:--|--:|
{% for d in rows %}
| {{ (d.name or d.mac or '이름 없음') | string | replace('|', '/') | replace('
', ' ') }} | {{ d.ip or '—' }} | {{ d.band or d.connection or '—' }} | {{ (d.rssi_dbm | string) ~ ' dBm' if d.rssi_dbm is not none else '—' }} |
{% endfor %}

이 목록은 **진단 버튼을 누른 순간의 실제 접속 기기**입니다. RSSI는 무선 신호 세기이며 연결 속도가 아닙니다.
{% endif %}

{% set agents = state_attr('sensor.iptime_ijimesi_jindan', 'agents') or [] %}
**공유기 역할:** {{ states('sensor.iptime_ijimesi_jindan') }}
{% if agents %}
{% for a in agents %}
- **{{ a.nickname or a.product_name or a.mac or '에이전트' }}** · 상태 {{ a.status or '미확인' }} · 백홀 {{ a.backhaul or a.connection or '속도 정보 없음' }}
{% endfor %}
{% else %}
진단에서 확인된 에이전트 정보가 없습니다.
{% endif %}
에이전트의 숫자 연결 속도는 공유기가 값을 제공할 때만 확인할 수 있습니다.

{% set stamp = state_attr('sensor.iptime_neteuweokeu_jindan', 'last_success') %}
{% if stamp %}
{% set age = (as_timestamp(now()) - as_timestamp(stamp)) | int %}
{% if age > 86400 %}⚠️ **지난 진단 결과** · {% else %}✅ **마지막 진단** · {% endif %}
{{ as_timestamp(stamp) | timestamp_custom('%m/%d %H:%M', true) }} ({{ relative_time(as_datetime(stamp)) }} 전)
{% else %}
ℹ️ **아직 상세 진단을 수집하지 않았습니다.** 아래 버튼을 누르면 새 결과가 표시됩니다.
{% endif %}

{% set lease_matches = states.sensor | selectattr('name', 'eq', 'ipTIME DHCP 임대 수') | list %}
{% set reserved_matches = states.sensor | selectattr('name', 'eq', 'ipTIME DHCP 수동 할당 수') | list %}
{% if not lease_matches or not reserved_matches %}
통합 업데이트와 HA 재시작 후 DHCP 목록이 표시됩니다.
{% else %}
{% set leases = lease_matches[0].attributes.get('entries', []) %}
{% set reserved = reserved_matches[0].attributes.get('entries', []) %}
**수동 할당 {{ reserved_matches[0].state }}개 · IP 숫자 순서**
{% if reserved %}
| IP | 기기 | MAC |
|:--|:--|:--|
{% for r in reserved %}| {{ r.ip }} | {{ (r.name or '설명 없음') | replace('|', '/') | replace('
', ' ') }} | {{ r.mac }} |
{% endfor %}
{% else %}수동 할당 목록이 비어 있거나 아직 수집되지 않았습니다.
{% endif %}

**DHCP 임대 {{ lease_matches[0].state }}개 · IP 숫자 순서**
{% if leases %}
| IP | 기기 | MAC |
|:--|:--|:--|
{% for r in leases %}| {{ r.ip }} | {{ (r.name or '이름 없음') | replace('|', '/') | replace('
', ' ') }} | {{ r.mac }} |
{% endfor %}
{% else %}임대 목록이 비어 있거나 아직 수집되지 않았습니다.
{% endif %}

임대 기록은 **현재 접속 중이라는 뜻이 아닙니다.** 실제 접속 여부는 연결 상세 탭에서 확인하세요.
{% endif %}

{% set matches = states.sensor | selectattr('name', 'eq', 'ipTIME 주요 설정 진단') | list %}
{% set e = matches[0] if matches else none %}
{% if not e %}
통합 업데이트와 HA 재시작 후 주요 설정을 볼 수 있습니다.
{% elif e.state in ['unavailable', 'unknown'] %}
확인 가능한 설정값이 없습니다. **상세 진단 수집**을 눌러 주세요.
{% else %}
{% for group, label in [('lan', 'LAN'), ('dhcp', 'DHCP'), ('dhcp_status', 'DHCP 상태'), ('wireless_channel', '무선 채널')] %}
{% set values = e.attributes.get(group) %}
{% if values %}
**{{ label }}**
{% for key, value in values.items() %}
- {{ key }}: {{ value }}
{% endfor %}
{% endif %}
{% endfor %}
공유기가 제공하지 않는 필드는 표시하지 않습니다. 이 화면에서는 설정을 변경하지 않습니다.
{% endif %}
